INSERT INTO "annotations" VALUES(193,'subashsah_wiseyak','fcc74e99dc7f35','कलम',2,'नाम (Noun)','बाँस निगालो वा धातुबाट बनेको लेख्ने साधन; लेखनी। , धानको नलजस्तो भित्र प्वाल परेको डाँठ हुने सानो बाँस; एक जातको निगालो सर। , असारमा रोपेर मङ्सिरमा पाक्ने एक जातको धान। , तस्बिर बनाउने हाते कुची; चित्र लेख्ने साधन।','sentence1','विद्यार्थीले परीक्षा भवनमा बसेर कालो मसी भएको कलमले उत्तरपुस्तिकामा लेख्न थाल्यो।','thumbs_up','','fcc74e99dc7f35.wav','2026-10-01T04:54:06.659441','2026-10-01T04:54:06.659441');
