INSERT INTO "annotations" VALUES(195,'subashsah_wiseyak','b18a81dc5fc871','कल्प',0,'नाम (Noun)','माङ्गलिक तथा शुभ कार्यका शास्त्रीय विधिविधान। , वेदका छ अङ्ग- शिक्षा कल्प व्याकरण निरुक्त छन्द र ज्योतिषमध्ये बलिदान यज्ञ आदिसित सम्बन्धित विधि बताउने एक अङ्ग। , हिन्दू पञ्चाङ्गअनुसार चौध मन्वन्तर वा एक हजार महायुग अर्थात् चार अरब बत्तिस करोड मानव वर्ष बताइएको कालका समयको साह्रै ठुलो विभाग। , पुराणअनुसार ब्रह्माको एक दिन मानिने प्रत्येक कल्प श्वेतवाराह नीललोहित वामदेव रथन्तर रौरव प्राण वृहत्कल्प कन्दर्प सत्य ईशान व्यान सारस्वत उदान गारुड कौर्म नारसिंह समान आग्नेय सोम मानव पुमान वैकुण्ठ लक्ष्मी सावित्री घोर वाराह वैराज गौरी माहेश्वर र पितृ। , आधुनिक पुराशास्त्र तथा भूशास्त्रका अनुसार कतिपय युगमा बाँडिएको र पृथ्वीको केही स्वतन्त्र विकासात्मक अवस्था हुने विशिष्ट कालविभाग आदिकल्प उत्तरकल्प मध्यकल्प नवकल्प इ। , प्रलय। , आयुर्वेद मतानुसार शरीरको कुनै अङ्गलाई पुनः नयाँ र स्वस्थ बनाउने युक्ति; वैद्यशास्त्रीय चिकित्सा विधान केशकल्प नेत्रकल्प कायाकल्प इ। ,पूर्ण वा वास्तविक नभए पनि समान वा बराबरी हुने; समान; तुल्य देवकल्प ऋषिकल्प इ।','sentence1','हिन्दु पौराणिक ग्रन्थअनुसार ब्रह्माको एक दिनलाई एक कल्प भनिन्छ, जसमा हजारौँ महायुगहरू व्यतीत हुन्छन्।','thumbs_up','','b18a81dc5fc871.wav','2026-10-01T04:54:26.095976','2026-10-01T04:54:26.095976');
INSERT INTO "annotations" VALUES(196,'subashsah_wiseyak','6961f44525ba94','कल्प',0,'नाम (Noun)','माङ्गलिक तथा शुभ कार्यका शास्त्रीय विधिविधान। , वेदका छ अङ्ग- शिक्षा कल्प व्याकरण निरुक्त छन्द र ज्योतिषमध्ये बलिदान यज्ञ आदिसित सम्बन्धित विधि बताउने एक अङ्ग। , हिन्दू पञ्चाङ्गअनुसार चौध मन्वन्तर वा एक हजार महायुग अर्थात् चार अरब बत्तिस करोड मानव वर्ष बताइएको कालका समयको साह्रै ठुलो विभाग। , पुराणअनुसार ब्रह्माको एक दिन मानिने प्रत्येक कल्प श्वेतवाराह नीललोहित वामदेव रथन्तर रौरव प्राण वृहत्कल्प कन्दर्प सत्य ईशान व्यान सारस्वत उदान गारुड कौर्म नारसिंह समान आग्नेय सोम मानव पुमान वैकुण्ठ लक्ष्मी सावित्री घोर वाराह वैराज गौरी माहेश्वर र पितृ। , आधुनिक पुराशास्त्र तथा भूशास्त्रका अनुसार कतिपय युगमा बाँडिएको र पृथ्वीको केही स्वतन्त्र विकासात्मक अवस्था हुने विशिष्ट कालविभाग आदिकल्प उत्तरकल्प मध्यकल्प नवकल्प इ। , प्रलय। , आयुर्वेद मतानुसार शरीरको कुनै अङ्गलाई पुनः नयाँ र स्वस्थ बनाउने युक्ति; वैद्यशास्त्रीय चिकित्सा विधान केशकल्प नेत्रकल्प कायाकल्प इ। ,पूर्ण वा वास्तविक नभए पनि समान वा बराबरी हुने; समान; तुल्य देवकल्प ऋषिकल्प इ।','sentence2','वैदिक यज्ञ, अनुष्ठान र संस्कारका नियमहरू व्यवस्थित रूपमा बुझ्न वेदाङ्ग अन्तर्गतको कल्पको अध्ययन गरिन्छ।','thumbs_up','','6961f44525ba94.wav','2026-10-01T04:54:36.221005','2026-10-01T04:54:36.221005');
