BEGIN TRANSACTION;
CREATE TABLE annotations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    annotator_id TEXT NOT NULL,
                    item_id TEXT NOT NULL,
                    word TEXT NOT NULL,
                    meaning_index INTEGER NOT NULL,
                    pos TEXT,
                    definition TEXT,
                    sentence_key TEXT,
                    sentence_text TEXT NOT NULL,
                    score TEXT NOT NULL, -- 'thumbs_up' or 'thumbs_down'
                    notes TEXT,
                    audio_filename TEXT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    UNIQUE(annotator_id, item_id),
                    FOREIGN KEY(annotator_id) REFERENCES annotators(annotator_id)
                );
CREATE TABLE annotators (
                    annotator_id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    email TEXT,
                    dialect TEXT,
                    experience TEXT,
                    notes TEXT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                , password_hash TEXT);
CREATE INDEX idx_annotator_item ON annotations(annotator_id, item_id);
CREATE INDEX idx_annotator_word ON annotations(annotator_id, word);
CREATE INDEX idx_annotator_score ON annotations(annotator_id, score);
DELETE FROM "sqlite_sequence";
COMMIT;
